// Shared RU i18n dictionary + translator. Brand strings interpolate APP_NAME
// from ./brand so the product name stays single-sourced. (The APK still has its
// own dictionary pending reconciliation; it will adopt this module next.)
import { APP_NAME } from "./brand";

// ── Канонические имена сущностей (менять ТОЛЬКО здесь) ─────────────
// Раздел /remote назывался шестью именами сразу: «Экран» (nav), «Рабочий
// стол» (quick/sys/remote.title и одновременно кнопка Win+D!), «Удалённый
// рабочий стол» (license.feature), «Remote Desktop» (license.matrix),
// «Экран компьютера» (home.guide), «Посмотреть экран компьютера»
// (home.steps). Первым каноном был «Экран ПК», но живой разбор 2026-07-27
// показал, что имя всё равно разъехалось на три: в сайдбаре «Экран ПК», в
// заголовке экрана запуска «Экран компьютера», во вкладке «Экран». Канон
// сменён на «Экран компьютера» — так раздел зовут сами его экраны, и это
// единственный вариант, который читается без расшифровки «ПК». Короткая
// подпись «Экран» (nav.remote.short) остаётся: её показывает CSS на узких
// экранах, и это усечение того же имени, а не другое слово.
const REMOTE = "Экран компьютера";
// Раздел SSH звался четырьмя способами сразу: «SSH-серверы» (вкладка),
// «Серверы по SSH» (секция в «Моих компьютерах»), «Серверы» (кнопка списка
// терминалов и текст пустого состояния) и «SSH-центр» (подсказки терминала);
// пятым именем шла подпись «Хосты, туннели, файлы» в настройках. Канон —
// «SSH-серверы»: слово «Серверы» без уточнения занято собственными машинами
// Remotai, а «центр» и «хосты» человек с ноутбуком не опознаёт.
const SSH = "SSH-серверы";
// Как зовут машину, у которой нет человеческого имени: при подключении по
// локальной сети вместо имени приходит адрес, и «127.0.0.1» стояло в шапке
// всех рабочих экранов, крупным заголовком на экране запуска удалёнки и
// строкой под именем в «Моих компьютерах». Имя одно на все эти места.
const THIS_PC = "Этот компьютер";
// Список машин аккаунта повторялся литералом «Мои компьютеры» в девяти ключах:
// вкладка, заголовок экрана, ссылка под плитками, чип, строка настроек, раздел
// гида, кнопка гида и два сообщения о потере связи. Каждый литерал — шанс
// разъехаться при следующем переименовании.
const DEVICES = "Мои компьютеры";
// «Система» стояла отдельным литералом во вкладке, в заголовке экрана, в строке
// гида на главной и в кнопке гида.
const SYSTEM = "Система";
// Раздел /agents звался «Агенты» семью литералами сразу: вкладка, заголовок
// экрана в облаке и вне его, карточка в «Системе», кнопка из строки квоты,
// строка гида на главной и место настройки в каталоге агента.
const AGENTS = "Агенты";

// ── Канонические подписи разделов (одна на раздел) ─────────────────
// Двери в один и тот же раздел описывали его РАЗНЫМИ словами: «Система» была
// «Процессор, память, диски и запущенные программы» в шторке «Ещё» и
// «Процессор, память, процессы; сон и выключение» на главной; у раздела агентов
// описаний было четыре — при том что комментарий над ключом прямо требовал
// одного. Три описания одного экрана человек читает как три разных экрана.
// Поэтому подпись — одна строка, а ключи ниже только ссылаются на неё; сами
// двери берут имя и подпись через apk/src/sections.ts (sectionName/sectionDesc).
const DEVICES_DESC = "Все компьютеры и серверы аккаунта, переключение между ними";
// Вариант для локального режима (окно exe, LAN): аккаунта там нет вовсе, и
// «все компьютеры аккаунта» — прямая неправда, клиент управляет одной машиной.
const DEVICES_DESC_LOCAL = "Компьютер, к которому вы подключены, и его SSH-серверы";
// «через этот компьютер» здесь не украшение: без этого факта непонятно, почему
// при выключенном ПК список серверов пуст.
const SSH_DESC = "Терминал, файлы и проброс портов на ваших серверах — через этот компьютер";
// «сон и выключение» — единственное упоминание питания во всех подписях
// разделов: при слиянии двух описаний его нельзя было потерять.
const SYSTEM_DESC = "Процессор, память, диски, процессы; сон и выключение";
const USAGE_DESC = "Беседы, скиллы, MCP, аккаунты и расход токенов";
// «устройств» → «компьютеров»: устройство в продукте — это телефон или браузер,
// которым человек вошёл, а машина с Remotai называется компьютером.
const PANEL_DESC = "Подключение телефона, обновления и доступ с других компьютеров аккаунта";
// «оформление» из подписи убрано: раздела оформления в настройках нет ни
// одного — это было обещание, которое некому выполнить.
const SETTINGS_DESC = "Уведомления, подключение, аккаунт и помощь";
const GUIDE_DESC = "Что умеет Remotai и как этим пользоваться: короткие статьи и примеры";

