  "guide.plan.body2": "Личный кабинет открывается из «Ещё». Там видно, каким аккаунтом вы вошли, какие машины подключены и до какого числа оплачен доступ. Покупка через СБП или карту оплачивает 30 дней; продление вручную, автоматических списаний нет. После оплаты можно проверить зачисление и обратиться в поддержку по чеку или возврату.",
  "guide.plan.body3": "Первые 7 дней через интернет — пробный период Про, карта не нужна (у зарегистрировавшихся до 08.09.2026 он остаётся 30-дневным); сколько дней осталось, видно в кабинете. Когда пробные или оплаченные дни закончатся, доступ через интернет выключится, а дома всё продолжит работать бесплатно. Продлить можно в любой момент той же кнопкой — списаний без вашего участия нет.",
