  // «Зафиксировать проблему» (ST-01): трасса клиента терминала, а не его вывод.
  // По умолчанию в файле только служебные события; вывод — лишь при явно
  // включённой записи, с предупреждением и отдельным согласием на отправку.
  "pty.traceOpen": "Зафиксировать проблему",
  "pty.traceTitle": "Зафиксировать проблему",
  "pty.traceSummary": "Событий: {events} за {seconds} с · вытеснено старых: {dropped}",
  "pty.traceStreamEvicted": "Кадры потока до seq {seq} вытеснены: {n} {n|запись|записи|записей}, приёма раньше этого места в файле нет.",
  "pty.traceMetaOnly": "В файле только служебные события: без вывода терминала, текста ввода и буфера обмена. Ввод человека — и нажатия, и вставка — сериями: без числа нажатий и интервалов, длина серии — только грубым диапазоном. Вывод, пришедший во время набора или вставки (эхо, звёздочки пароля), — тоже одним грубым диапазоном, без кадров и позиций потока; так же — повторная досылка потока с места до конца набора (переподключение). Позиции потока после набора отсчитываются от его конца, после перезапуска потока на компьютере — заново, а накопленные счётчики потока, в которые мог войти набор, пишутся только грубо: объём вывода — диапазоном и округлённым числом строк на килобайт, точного числа байт в файле нет; счётчики строк и глубина истории — как есть, длины набранного в них нет. Поэтому по самому файлу нельзя вычислить, сколько символов набрано или вставлено, даже при повторе неверного пароля. Исключение одно: компьютер после набора проиграл тот же вывод с самого начала — так бывает, когда Remotai обновился, а терминал был открыт версией 2.57.20 или раньше; тогда длину вычислить можно. Журнал Remotai на компьютере получает позиции потока без пересчёта: вместе с ним длину набранного вычислить можно.",
  "pty.traceBytesWarn": "В файл попадёт записанный вывод терминала: {kb} КБ, {chunks} {chunks|фрагмент|фрагмента|фрагментов}. В нём могут быть пароли и ключи — смотрите, кому отдаёте.",
  "pty.traceTruncated": "Начало записи вытеснено лимитом.",
