  // Connection
  "conn.reconnecting": "Переподключение…",
  "conn.reconnected": "Подключено",
  "conn.offline": "Нет соединения с компьютером",
  "conn.pcOffline": "Компьютер не в сети",
  "conn.serverOffline": "Сервер не в сети",
  // С именем — когда машина известна. У человека их может быть десять, и
  // безличное «Компьютер не в сети» не отвечает ни «какой», ни «что делать»:
  // живой случай — привязал сервер, переключился на него, а сверху висит
  // «Компьютер не в сети», хотя вторая машина в это время работает.
  // ── Локальное управление и вход в аккаунт (главная) ───────────────
  // Человек должен понимать, ЧТО У НЕГО СЕЙЧАС, а не только что ему предлагают:
  // «сейчас управление локальное» объясняет, почему компьютер виден лишь дома и
  // почему список машин пуст, а вход в аккаунт — это переход к управлению
  // откуда угодно. Живая жалоба: «теперь не пойму, где мне зайти в аккаунт?»
  // (после того как окно на ПК стало открывать приложение, а не панель).
  "home.signin.title": "Сейчас управление локальное",
  "home.signin.desc": "Вы работаете с этим компьютером напрямую — с него самого или по домашней сети. Чтобы управлять им откуда угодно и держать рядом другие компьютеры и серверы, войдите в аккаунт.",
  "home.signin.btn": "Войти в аккаунт",
  // Объяснение (28 слов) уехало под раскрытие: на первом экране оно было
  // четвёртой обучающей поверхностью подряд. Удалять его нельзя — это и есть
  // ответ на ту самую жалобу, поэтому текст остаётся, но по запросу.
  "home.signin.more": "Подробнее",

  // Машина привязана, но её агент НИ РАЗУ не выходил на связь — это не
  // «выключена», а «ещё не запущена». Живой вопрос владельца: «почему сервер,
  // что я подключил, не в сети?» — он привязал сервер командой remotai pair, но
  // не запустил службу.
  "infra.neverOnline": "Ещё ни разу не выходил на связь",
  "infra.neverOnlineServer": "Сервер привязан, но его служба ещё не запущена. Выполните на сервере:",
  "infra.neverOnlinePc": "Компьютер привязан, но Remotai на нём ещё не запускался. Запустите приложение на этом компьютере.",

  "conn.pcOfflineNamed": "«{name}» не в сети",
