  "sys.holdTooShort": "Удерживайте кнопку около секунды — так подтверждается действие",
  "sys.killProtected": "Процесс защищён — нужны права администратора.",
  // Отказ по существу, а не по правам: ядро ОС (PID 4 в Windows, PID 1 в
