  // Справка экрана «Агенты». Жаргона тут больше, чем где-либо в продукте:
  // окно, аккаунт, подписка, ключ — четыре слова, каждое из чужого словаря.
  // Раньше два объяснения лежали карточками внизу свитка, где их читал тот,
  // кто долистал; теперь они под «?» в шапке, где их ищут.
  "agents.helpTitle": AGENTS,
  "agents.help.windowTitle": "Что такое 5-часовое окно",
  "agents.help.windowText": "Claude и ChatGPT дают лимит не на сутки, а на скользящие несколько часов: он тратится по мере работы и целиком восстанавливается ко времени сброса. Мы показываем остаток: «осталось 9%» значит, что до сброса хватит примерно на десятую часть обычной работы. Когда именно сбросится — в строке под названием окна.",
  "agents.help.accountTitle": "Аккаунт и подписка — не одно и то же",
  "agents.help.accountText": "Аккаунт агента — это отдельная папка на компьютере со своим входом. Их можно завести несколько: вторая подписка не выкидывает из первой, они живут рядом. Вход делается внутри самого агента в терминале, а здесь вы выбираете, под каким аккаунтом он запустится в следующий раз.",
  "agents.help.openrouterTitle": "Зачем ключ OpenRouter",
  "agents.help.openrouterText": "Если подписки на Claude или ChatGPT нет, один ключ OpenRouter заменяет счёт у каждого сервиса: агент работает на любой из сотен моделей, в том числе бесплатных. Ключ хранится на компьютере и на телефон не приезжает. Подхватят его только терминалы, открытые после подключения.",
  "usage.accountCurrent": "сейчас",
  "usage.accountCurrentHint": "Этим аккаунтом запускается агент на этом компьютере",
  "usage.extraTitle": "Дополнительное использование",
  "usage.extraAmount": "{used} из {limit}",
  "usage.source": "Источник: {source}",
  "usage.coverageTitle": "Покрытие сводки",
  "usage.coverageAnswered": "Получены ответы: {answered} из {online} {online|устройства|устройств|устройств} в сети.",
  "usage.coverageOffline": "Не в сети: {count} — их лимиты появятся после подключения.",
  "usage.footnoteTitle": "Почему у некоторых сервисов нет процентов?",
  "usage.footnoteText": `${APP_NAME} показывает только те данные, которые сам сервис отдаёт через безопасный локальный запрос. Для клиентов без такого запроса мы отмечаем ограничение явно и не читаем токены из истории чатов.`,

  // Чип квоты на профиле агента (настройки → агенты, выбор агента на дашборде).
  // «Недоступно» — честный серый «?», никогда не «0%»: неизвестная квота
  // не равна нулевой (unknown cost is never $0).
  "quota.fiveHour": "5ч",
  "quota.sevenDay": "7д",
  // Подсказка обязана говорить то же, что число на чипе: чип показывает
  // ОСТАТОК (одна шкала на весь продукт), поэтому и здесь «осталось».
  "quota.fiveHourTitle": "5-часовое окно {name}: осталось {pct}%",
  "quota.sevenDayTitle": "Недельный лимит {name}: осталось {pct}%",
  "quota.unknownTitle": "Лимиты {name} ещё не получены — появятся сами через пару минут",

