  "license.devicesLimitNote": "Когда компьютеров станет {max}, новый добавить не выйдет, пока не удалить старый",
  // Биллинг уже включён, а числа цены в данных нет: обещать конкретную сумму
  // нельзя, но сказать, что бесплатное кончилось и что именно осталось
  // бесплатным, — можно. Совпадает по смыслу с license.beta.note.
  "license.pricePaid": "Серверы и облачный доступ входят в Про. Локальная работа на своём компьютере бесплатна.",
  // Граница денег продукта одной фразой. Человек должен понимать не «какой у
  // меня тариф», а что именно он теряет и чего не теряет никогда.
  "license.homeFree": "Локальная работа на своём компьютере бесплатна навсегда. Серверы, SSH/SFTP, проброс портов и облачный доступ требуют Про, в том числе из локальной сети.",
  "license.trialLeft": "Проба Про: осталось {days} дн.",
  "license.trialLeftOne": "Проба Про: остался последний день",
  "license.cloudOn": "Удалённый доступ работает",
