  // Не «доступ заблокирован»: человек ничего не потерял, выключено расстояние.
  "license.cloudOffNote": "Терминалы, агенты и файлы на своём компьютере доступны локально. Для серверов и облачного доступа нужна подписка.",
  "license.matrix.servers": "Серверы, SSH/SFTP",
