  // Формулировки те же, что в режимах потока удалёнки (remote.profileDesc.*).
  "license.matrix.remoteFree": "Чуть рывками",
  "license.matrix.remotePro": "Плавно и чётко",
  "license.matrix.terminals": "Терминалы",
