  "home.status.onlineNamed": "{name} на связи",
  // Состояние отдельно от имени. «{name} на связи» одной строкой резалось на
  // «Рабочий компьютер на…» — пропадало ровно то слово, ради которого приложение
  // открыли. Теперь ReadyCard печатает «На связи · Рабочий компьютер»: сначала
  // ответ, потом имя, и обрезаться имеет право только имя. Без имени (LAN,
  // адрес вместо имени) остаётся полная фраза home.status.online.
  "home.status.onlineShort": "На связи",
  // Теми же словами, что и раздел «Система» (sys.cpu, sys.memory): «CPU 27% ·
  // RAM 68%» и «Процессор, память» строкой ниже — это одно и то же на одном
  // экране, названное на двух языках.
  "home.status.load": "процессор {cpu}% · память {ram}%",
  // Тревожный показатель вытесняет пару «процессор · память»: два спокойных
  // числа в строке заслоняли то единственное, из-за которого компьютер и
  // встанет. Слова те же, что в паре выше, — иначе один и тот же замер
  // назывался бы на главной двумя языками.
  "home.status.worst": "{label} {n}%",
  "home.status.metric.cpu": "процессор",
  "home.status.metric.ram": "память",
  "home.status.metric.disk": "диск",
  // Диск: свою проверку агент не присылает, её считает клиент. Заполненный диск
  // роняет сборки и агентов задолго до того, как порвётся связь, — но это НЕ
  // ответ на вопрос «жив ли компьютер», поэтому отдельная строка, а не цвет
  // карточки. Имя тома и «свободно из» — теми же словами, что раздел «Система».
  "home.status.diskLabel": "Диск",
  "home.status.diskLow": "Диск {volume} почти полон — свободно {free} из {total}",
  "home.status.diskNote": "{volume} · занято {percent}% · свободно {free}",
  // Плашка про версию АГЕНТА на главной (agentUpdateNotice). «Сильно устарел»
