  "home.agentUpdateStuck": "На {device}: {version} сильно устарела (актуальная {latest}) — обновите в «Настройках»",
  "home.agentUpdateReady": "Обновление {latest} скачано — применим, когда никто не работает",
  "home.agentUpdateAvailable": "Вышла {latest} — установится автоматически",
  // Живая сводка: что требует ответа, что работает, куда вернуться
  "home.act.attention": "Требует внимания",
  "home.act.running": "Сейчас работает",
  // Заголовок той же секции, когда никто не печатает: только освободившиеся агенты.
  "home.act.agents": "Агенты",
  // …а когда AI-агента в списке нет вовсе — «Агенты» над голыми PowerShell'ами
