  "home.act.terminals": "Открытые терминалы",
  "home.act.answer": "Ответить",
  "home.act.open": "Открыть",
  "home.act.errorShort": "ошибка",
  "home.act.errorHint": "Последняя команда завершилась ошибкой",
  // «Вывод» человек читает как «заключение», а не как «то, что напечатал
