  "agentLaunch.afterNodeText": "Команда установки Node.js ушла в терминал. Когда она закончится, npm в ЭТОМ терминале ещё не виден — PATH обновляется только у новых процессов. Нажмите «Обновить PATH», а потом «Проверить снова».",
  "agentLaunch.afterInstallText": "Команда установки ушла в терминал. Дождитесь её окончания и нажмите «Проверить снова» — установленный агент появится в списке сверху.",
  "agentLaunch.emptyInstalled": "На компьютере пока нет ни одного AI-агента. Поставьте любой — команда уйдёт в этот терминал.",
