  "pty.helpAgentTitle": "AI-агенты",
  "pty.helpAgentText": "Кнопка «Запустить AI-агента» открывает выбор папки, а затем список агентов (Claude Code, Codex, Gemini): установленные запускаются сразу, остальные ставятся одной командой. Завершённый терминал с агентом предлагает «Продолжить» — беседа продолжится с того же места.",
  "pty.helpGroupsTitle": "Группы и порядок",
