  "pty.termHelpAgentText": "Кнопка «Агент» в нижней клавиатуре, в разделе «Ещё», запускает Claude Code или другого агента в текущей папке. Когда агент задаёт вопрос, кнопки ответа появляются в янтарной полосе над полем ввода.",
  "pty.termHelpScrollTitle": "Прокрутка",
  "pty.termHelpScrollText": "Проведите пальцем по выводу. Кнопки справа листают вверх, вниз, в начало и в конец. Кнопка «Вывод» в шапке выбирает режим: «Авто» подбирает его сам, «Вывод» листает накопленный текст, «Агент» — историю внутри программы.",
  "pty.termHelpSelectTitle": "Копирование",
