  "guide.action.openBehaviour": "Открыть настройки запуска агентов",
  "guide.settingsOverview.title": "Настройки приложения",
  "guide.settingsOverview.lead": "Компьютер, подключение, уведомления и аккаунт.",
  "guide.settingsOverview.body": "Откройте «Настройки» и выберите нужную группу. В «Компьютере» находятся автозапуск и доступ с других устройств; в «Подключении» — проверка связи и обновления; в «Аккаунте» — способы входа.",
  "guide.agentSleep.title": "Усыпить агента",
  "guide.agentSleep.lead": "В терминале: «⋮ Ещё» → «Усыпить», затем «Разбудить».",
  "guide.agentSleep.body": "Сон агента включается в его терминале: «⋮ Ещё» → «Усыпить». Это доступно для простаивающих Claude Code и Codex на компьютере. Вкладка остаётся; кнопка «Разбудить» продолжит беседу.",
  "guide.agentSessions.body": "Здесь собраны прошлые беседы Claude Code и Codex на выбранном компьютере. Найдите разговор по теме или папке и продолжите его; уже открытая беседа вернёт вас в свой терминал.",
  "guide.agentSkills.lead": "Установить, скопировать или удалить умения агента.",
  "guide.agentSkills.body": "Откройте «Агенты» → «Скиллы». Можно установить скилл по ссылке GitHub или из ZIP, скопировать другому агенту и вернуть после удаления.",
  "guide.agentMcp.lead": "Добавить агенту инструменты без правки JSON.",
  "guide.agentMcp.body": "В «Агенты» → «MCP-серверы» можно добавить сервер, посмотреть подключения и выключить ненужное. Изменение начнёт работать при следующем запуске агента.",
  "guide.agentCheck.lead": "Выберите агента в «Установлены», чтобы проверить вход и модель.",
  "guide.agentCheck.body": "В «Агенты» → «Установлены на компьютере» выберите «Проверить подключение» у нужного агента. Сначала увидите адрес, источник ключа или подписки и модель; настоящий проверочный запрос отправляется только после отдельного нажатия.",
  "guide.agentUpdate.title": "Обновить агента",
  "guide.agentUpdate.lead": "Новая версия появится рядом с агентом в «Установлены».",
  "guide.agentUpdate.body": "В «Агенты» → «Установлены на компьютере» рядом с Claude Code, Codex или другим CLI появится «Обновить», если доступна новая версия. Обновление использует тот же менеджер, которым агент установлен.",
  "guide.agentBehaviour.lead": "Выбрать агента по умолчанию и кнопки ответов на его вопросы.",
  "guide.agentBehaviour.body": "В «Агенты» → «Как запускаются» выберите агента для быстрого запуска и включите или выключите кнопки 1/2/3 для вопросов в терминале. Изменения действуют на выбранном компьютере.",
  "guide.tokenUsage.lead": "Посмотреть, куда ушли токены по дням, моделям и беседам.",
  "guide.tokenUsage.body": "Откройте «Агенты» → «Расход токенов». Компьютер считает использование по локальным файлам бесед; здесь видны дни, аккаунты, модели, папки и сессии.",
  "guide.computerPower.title": "Сон и перезагрузка компьютера",
  "guide.computerPower.lead": "Управлять питанием выбранного компьютера.",
  "guide.computerPower.body": "Откройте «Система» → «Питание», чтобы перевести компьютер в сон, перезагрузить или выключить. Спящий компьютер пропадёт из приложения; разбудить его удалённо нельзя.",
  "guide.sshAdd.lead": "Сохранить адрес, ключ или пароль сервера.",
  "guide.sshAdd.body": "Откройте «SSH-серверы» и нажмите «Добавить SSH-сервер» вверху. Раздел доступен даже до первого сохранённого сервера; подключение идёт через выбранный компьютер.",
  "guide.action.openPanel": "Открыть панель ПК",
  "guide.supportRow": "Написать в поддержку",
