  "research.safetyTitle": "Защитные меры",
  "research.safetyHint": "Не дайте ИИ обмануть метрику или сломать код",
  "research.invariants": "Проверка инвариантов",
  "research.invariantsHint": "Запускается после каждого эксперимента. Если команда падает (код выхода ≠ 0), эксперимент откатывается независимо от улучшения метрики. Например: ваш набор тестов.",
