/**
 * Русское склонение по числу: 1 — «агент», 2–4 — «агента», 5+ — «агентов»
 * (11–14 и 111 идут в третью форму, как и положено).
 *
 * Зачем: интерфейс писал «Найдено 1 агентов», «Закрыто 1 сессий», «Туннели: 1
 * активных» — машинный вывод вместо речи. Хелпер один на весь проект: до него
 * склонятор существовал ровно в одном месте (deviceCountLabel в
 * InfrastructureView), и остальные ключи обходились формой множественного
 * числа.
 *
 * В словаре то же самое доступно прямо в шаблоне: `{n|агент|агента|агентов}`
 * (см. t()) — тогда склонение не требует правок в коде экрана.
 */
export function plural(n: number, forms: [string, string, string]): string {
  const abs = Math.abs(Math.trunc(n));
  const mod10 = abs % 10;
  const mod100 = abs % 100;
  if (mod10 === 1 && mod100 !== 11) return forms[0];
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 10 || mod100 >= 20)) return forms[1];
  return forms[2];
}

/** Токен склонения в шаблоне: `{n|агент|агента|агентов}`. */
const PLURAL_TOKEN_RE = /\{(\w+)\|([^|{}]*)\|([^|{}]*)\|([^|{}]*)\}/g;

export function t(key: string, params?: Record<string, string | number>): string {
  const found = Object.prototype.hasOwnProperty.call(ru, key);
  if (!found && import.meta.env.DEV) {
    console.warn(`[i18n] Missing key: ${key}`);
  }
  let text = found ? ru[key] : (import.meta.env.DEV ? `⟦${key}⟧` : key);
  if (params) {
    // Склонение — ДО простой подстановки: `{n}` внутри `{n|…|…|…}` не тронут,
    // потому что replace ищет литеральную строку «{n}», а не подстроку.
    text = text.replace(PLURAL_TOKEN_RE, (whole, name: string, one: string, few: string, many: string) => {
      const raw = params[name];
      const num = typeof raw === "number" ? raw : Number(raw);
      if (!Number.isFinite(num)) return whole; // параметр не передали — оставляем токен видимым в DEV
      return plural(num, [one, few, many]);
    });
    for (const [k, v] of Object.entries(params)) {
      text = text.replace(`{${k}}`, String(v));
    }
  }
  return text;
}
